import './globals.css';
import type { Metadata } from 'next';
import { Inter } from 'next/font/google';

const inter = Inter({ subsets: ['latin'] });

export const metadata: Metadata = {
  title: 'EaseMize Chat',
  description: 'A simple chat application',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en" className={inter.className}>
      <body>{children}</body>
    </html>
  );
}

import ChatLayout from '@/components/ChatLayout';

export default function Page() {
  return (
    <ChatLayout />
  );
}

'use client';

import { useState } from 'react';
import ChatSidebar from '@/components/ChatSidebar';
import MessageList from '@/components/MessageList';
import PromptInput from '@/components/PromptInput';
import EmptyState from '@/components/EmptyState';

export default function ChatLayout() {
  const [messages, setMessages] = useState<Array<{ id: number; role: 'user' | 'assistant'; content: string }>>([]);
  const [isLoading, setIsLoading] = useState(false);

  const handleSendMessage = async (content: string) => {
    // Add user message
    const userMessage = { id: Date.now(), role: 'user', content };
    setMessages(prev => [...prev, userMessage]);
    setIsLoading(true);

    // Simulate assistant response with streaming
    // We'll break the response into chunks and update every 100ms
    const assistantResponse = `I received your message: "${content}". This is a simulated streaming response from the assistant.`;
    const chunks = assistantResponse.split(' ');
    let accumulated = '';

    for (let i = 0; i < chunks.length; i++) {
      await new Promise(resolve => setTimeout(resolve, 100)); // 100ms delay
      accumulated += chunks[i] + (i < chunks.length - 1 ? ' ' : '');
      setMessages(prev => {
        // Replace the last message if it's the assistant's, or add a new one
        const last = prev[prev.length - 1];
        if (last && last.role === 'assistant') {
          return [...prev.slice(0, -1), { ...last, content: accumulated }];
        }
        return [...prev, { id: Date.now() + i, role: 'assistant', content: accumulated }];
      });
    }

    setIsLoading(false);
  };

  return (
    <div className="flex h-screen bg-gray-50">
      <ChatSidebar />
      <div className="flex-1 flex flex-col">
        {messages.length === 0 ? (
          <EmptyState />
        ) : (
          <MessageList messages={messages} isLoading={isLoading} />
        )}
        <PromptInput onSend={handleSendMessage} isLoading={isLoading} />
      </div>
    </div>
  );
}

import Link from 'next/link';

export default function ChatSidebar() {
  return (
    <div className="w-64 border-r border-gray-200 bg-white p-4">
      <h2 className="text-lg font-semibold mb-4">Conversations</h2>
      <nav className="space-y-2">
        <Link href="/" className="flex items-center px-3 py-2 rounded-md text-sm font-medium hover:bg-gray-100">
          <svg className="mr-3 h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
          </svg>
          New Chat
        </Link>
        {/* Example conversation */}
        <Link href="/" className="flex items-center px-3 py-2 rounded-md text-sm font-medium hover:bg-gray-100">
          <svg className="mr-3 h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
          </svg>
          Previous Chat
        </Link>
      </nav>
    </div>
  );
}

export default function EmptyState() {
  return (
    <div className="flex-1 flex flex-col items-center justify-center py-12">
      <svg className="h-12 w-12 text-gray-400 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h11a2 2 0 012 2v10a2 2 0 01-2 2z" />
      </svg>
      <h2 className="text-lg font-semibold mb-2">How can I help you today?</h2>
      <p className="text-sm text-gray-500">Ask me anything and I'll do my best to assist you.</p>
    </div>
  );
}

import { marked } from 'marked';

type Message = {
  id: number;
  role: 'user' | 'assistant';
  content: string;
};

export default function MessageList({ messages, isLoading }: { messages: Message[]; isLoading: boolean }) {
  return (
    <div className="flex-1 overflow-y-auto p-4 space-y-4">
      {messages.map((message) => (
        <div key={message.id} className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}>
          <div className={`max-w-xl px-4 py-2 rounded-lg ${
            message.role === 'user' ? 'bg-blue-500 text-white' : 'bg-gray-200 text-gray-800'
          }`}>
            {/* Render markdown for assistant messages, plain text for user messages */}
            {message.role === 'assistant' ? (
              <div dangerouslySetInnerHTML={{ __marked: marked.parse(message.content) }} />
            ) : (
              <p>{message.content}</p>
            )}
          </div>
        </div>
      ))}
      {isLoading && (
        <div className="flex justify-start">
          <div className="px-4 py-2 rounded-lg bg-gray-200 text-gray-800 animate-pulse">
            Assistant is typing...
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useRef } from 'react';

export default function PromptInput({ onSend, isLoading }: { onSend: (content: string) => Promise<void>; isLoading: boolean }) {
  const [input, setInput] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  const handleSubmit = async () => {
    if (input.trim() === '') return;
    await onSend(input);
    setInput('');
    textareaRef.current?.focus();
  };

  return (
    <div className="flex items-center p-4 border-t border-gray-200 bg-white">
      <textarea
        ref={textareaRef}
        value={input}
        onChange={(e) => setInput(e.target.value)}
        onKeyDown={handleKeyDown}
        placeholder="Type a message..."
        className="flex-1 min-h-[44px] resize-none p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none disabled:opacity-50"
        disabled={isLoading}
      />
      {!isLoading && (
        <button
          onClick={handleSubmit}
          disabled={input.trim() === ''}
          className="ml-3 px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Send
        </button>
      )}
      {isLoading && (
        <div className="ml-3 h-4 w-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
      )}
    </div>
  );
}

